import ast,hashlib,pathlib
root=pathlib.Path('/workspace/source')
keys=('observe','stop','publish','handoff','release','main','review')
for p in sorted(root.rglob('*')):
 if p.suffix not in {'.py','.c'} or 'incoming' in p.parts: continue
 b=p.read_bytes(); rel=p.relative_to(root).as_posix()
 print(rel, len(b), hashlib.sha256(b).hexdigest()[:16])
 if p.suffix!='.py':
  continue
 t=ast.parse(b.decode())
 for n in t.body:
  if isinstance(n, ast.If):
   te=n.test
   if isinstance(te, ast.Compare) and any(isinstance(x, ast.Constant) and x.value=='__main__' for x in te.comparators):
    print(' ENTRY', rel, n.lineno)
  if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)) and any(k in n.name.lower() for k in keys):
   print(' DEF', n.name, rel, n.lineno)
   if isinstance(n, ast.ClassDef):
    for s in n.body:
     if isinstance(s,(ast.FunctionDef,ast.AsyncFunctionDef)) and any(k in s.name.lower() for k in keys):
      print('  M', s.name, s.lineno)
